From 16f7f299824fecc0087762a4beedcc184654dca0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:12:07 +0100
Subject: [PATCH] formatter: Format fractional time values instead of showing
 zero

Chart axis labels pass values as strings such as "47377.75", and the
time and ticks formatters read them with toLongLong(), which fails for
those strings and showed 0:00:00. Read them as doubles and round instead.

BUG: 521258
---
 formatter/Formatter.cpp | 4 ++--
 1 file changed, 2 insertions(+), 2 deletions(-)

diff --git a/formatter/Formatter.cpp b/formatter/Formatter.cpp
index e42210be..c96d7862 100644
--- a/formatter/Formatter.cpp
+++ b/formatter/Formatter.cpp
@@ -534,12 +534,12 @@ static QString formatNumber(const QVariant &value, Unit unit, MetricPrefix prefi

 static QString formatTime(const QVariant &value)
 {
-    return KFormat().formatDuration(value.toLongLong() * 1000);
+    return KFormat().formatDuration(qRound64(value.toDouble()) * 1000);
 }

 static QString formatTicks(const QVariant &value)
 {
-    auto seconds = value.toLongLong() / sysconf(_SC_CLK_TCK);
+    auto seconds = qRound64(value.toDouble()) / sysconf(_SC_CLK_TCK);
     return KFormat().formatDuration(seconds * 1000);
 }

